import React, { useState } from 'react';
import Header from '../components/Header';
import Footer from '../components/Footer';
import { UserPlus, BarChart3, Camera, Bell } from 'lucide-react';

const AdminPage = ({ userName }) => {
  const [requests, setRequests] = useState([
    { id: 1, name: 'محمد علي', status: 'معلق' },
    { id: 2, name: 'سارة أحمد', status: 'مكتمل' },
    { id: 3, name: 'خالد يوسف', status: 'معلق' },
  ]);

  const [subscribers, setSubscribers] = useState(125); // مثال عدد المشتركين

  return (
    <div className="flex flex-col min-h-screen" dir="rtl">
      <Header />

      <main className="flex flex-1 bg-gray-50 p-6 gap-6">
        {/* Left section - notifications table */}
        <section className="flex-1 bg-white rounded-xl shadow p-6">
          <h2 className="text-2xl font-bold mb-4">مرحباً {userName}</h2>
          <h3 className="text-xl font-semibold mb-4">طلبات المستخدمين</h3>

          <table className="w-full border-collapse text-right">
            <thead>
              <tr className="bg-gray-200">
                <th className="border p-2">الاسم</th>
                <th className="border p-2">الحالة</th>
              </tr>
            </thead>
            <tbody>
              {requests.map((req) => (
                <tr key={req.id} className="hover:bg-gray-100">
                  <td className="border p-2">{req.name}</td>
                  <td className="border p-2">
                    <span
                      className={`px-2 py-1 rounded text-white ${
                        req.status === 'معلق' ? 'bg-yellow-500' : 'bg-green-500'
                      }`}
                    >
                      {req.status}
                    </span>
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        </section>

        {/* Right sidebar */}
        <aside className="w-64 flex-shrink-0 flex flex-col gap-4">
          <button className="flex items-center gap-2 bg-blue-600 text-white p-3 rounded font-bold hover:bg-blue-700">
            <UserPlus /> إضافة مستخدم
          </button>

          <button className="flex items-center gap-2 bg-green-600 text-white p-3 rounded font-bold hover:bg-green-700">
            <BarChart3 /> إضافة رسم بياني
          </button>

          <button className="flex items-center gap-2 bg-purple-600 text-white p-3 rounded font-bold hover:bg-purple-700">
            <Camera /> إضافة كاميرا
          </button>

          <div className="bg-white p-4 rounded-xl shadow text-center">
            <h4 className="font-semibold mb-2">عدد المشتركين</h4>
            <p className="text-2xl font-bold">{subscribers}</p>
          </div>
        </aside>
      </main>

      <Footer />
    </div>
  );
};

export default AdminPage;
